<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {PROVIDERS,type ProviderId,type ProviderRun} from '../../shared/types'
import {bridge} from './bridge'
import ProviderLogo from './ProviderLogo.vue'
import IconButton from './IconButton.vue'
const props=defineProps<{groupId:string;members:ProviderId[];runs:ProviderRun[];suspended:boolean}>()
const root=ref<HTMLElement>(),selected=ref<ProviderId[]>([]),ordered=ref<ProviderId[]>([]),dragging=ref<ProviderId|null>(null),error=ref('')
const pageStates=ref<Partial<Record<ProviderId,{loading:boolean;error:string}>>>({})
let observer:ResizeObserver|undefined,frame=0,alive=true,poll:ReturnType<typeof setInterval>|undefined
async function retry(id:ProviderId){try{pageStates.value[id]={loading:true,error:''};await bridge.reloadProvider?.({groupId:props.groupId,provider:id});schedule()}catch(e){error.value=String(e)}}
const info=(id:ProviderId)=>PROVIDERS.find(p=>p.id===id)!
const expandedCount=computed(()=>selected.value.length)
function label(id:ProviderId){const status=props.runs.find(r=>r.provider===id)?.status;return status==='sending'?'发送中':status==='streaming'?'生成中':status==='uncertain'?'待核对':status==='login-required'?'请登录':'原网页'}
function save(){try{localStorage.setItem('council-native-'+props.groupId,JSON.stringify({selected:selected.value,order:ordered.value}))}catch{}}
function expand(id:ProviderId){if(!selected.value.includes(id))selected.value=[...selected.value,id];save();schedule()}
function expandAll(){selected.value=[...ordered.value];save();schedule()}
function focus(id:ProviderId){selected.value=[id];save();schedule()}
function collapse(id:ProviderId){if(selected.value.length<2)return;selected.value=selected.value.filter(p=>p!==id);save();schedule()}
function startDrag(event:DragEvent,id:ProviderId){dragging.value=id;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',id)}void sync()}
function endDrag(){dragging.value=null;schedule()}
function drop(event:DragEvent,id:ProviderId){const from=dragging.value;if(!from||from===id){endDrag();return}const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();const after=event.clientX>rect.x+rect.width/2;const order=ordered.value.filter(p=>p!==from);order.splice(order.indexOf(id)+(after?1:0),0,from);ordered.value=order;save();endDrag()}
function move(id:ProviderId,offset:number){const order=[...ordered.value],index=order.indexOf(id),next=index+offset;if(next<0||next>=order.length)return;[order[index],order[next]]=[order[next],order[index]];ordered.value=order;save();schedule()}
async function sync(){
 if(!alive)return
 await nextTick();if(!alive)return
 const panes=props.suspended||dragging.value?[]:[...root.value?.querySelectorAll<HTMLElement>('[data-native-provider]')||[]].map(el=>{const r=el.getBoundingClientRect();return {provider:el.dataset.nativeProvider as ProviderId,bounds:{x:Math.ceil(r.x),y:Math.ceil(r.y),width:Math.max(1,Math.floor(r.width)-1),height:Math.max(1,Math.floor(r.height)-1)}}}).filter(p=>p.bounds.width>1&&p.bounds.height>1)
 try{const states=await bridge.nativeLayout?.({groupId:props.groupId,panes});if(alive){for(const state of states||[])pageStates.value[state.provider]=state;error.value=''}}catch(e){if(alive)error.value=e instanceof Error?e.message:String(e)}
}
function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>void sync())}
watch(()=>props.suspended,()=>void sync(),{flush:'post'})
watch(()=>props.members.join(','),()=>{ordered.value=[...ordered.value.filter(id=>props.members.includes(id)),...props.members.filter(id=>!ordered.value.includes(id))];selected.value=selected.value.filter(id=>props.members.includes(id));if(!selected.value.length&&props.members.length)selected.value=[props.members[0]];schedule()})
onMounted(()=>{poll=setInterval(()=>{if(!dragging.value&&!props.suspended)schedule()},400);try{const v=JSON.parse(localStorage.getItem('council-native-'+props.groupId)||'{}');ordered.value=(Array.isArray(v.order)?v.order:[]).filter((id:ProviderId)=>props.members.includes(id));selected.value=(Array.isArray(v.selected)?v.selected:props.members).filter((id:ProviderId)=>props.members.includes(id))}catch{}ordered.value=[...ordered.value,...props.members.filter(id=>!ordered.value.includes(id))];if(!selected.value.length)selected.value=[...props.members];observer=new ResizeObserver(schedule);if(root.value)observer.observe(root.value);window.addEventListener('resize',schedule);void nextTick(()=>{root.value?.querySelectorAll('[data-native-provider]').forEach(el=>observer?.observe(el));schedule()})})
watch(selected,()=>void nextTick(()=>{root.value?.querySelectorAll('[data-native-provider]').forEach(el=>observer?.observe(el));schedule()}))
onBeforeUnmount(()=>{alive=false;clearInterval(poll);cancelAnimationFrame(frame);observer?.disconnect();window.removeEventListener('resize',schedule);void bridge.nativeLayout?.({groupId:props.groupId,panes:[]}).catch(()=>{})})
</script>
<template>
<section class="native-conversation" ref="root" aria-label="AI 原网页工作区">
 <div class="native-toolbar"><button class="expand-all" @click="expandAll" :disabled="selected.length===members.length">展开全部 {{members.length}} 位成员</button><span>拖动栏头调整顺序 · 展示选择不影响发送对象</span></div>
 <div v-if="error" class="native-error" role="alert">{{error}}<button @click="schedule">重新加载视图</button></div>
 <div class="native-columns" :class="{'is-dragging':dragging}">
  <template v-for="id in ordered" :key="id">
   <article v-if="selected.includes(id)" class="native-column" :data-column="id" @dragover.prevent @drop.prevent="drop($event,id)"><header draggable="true" @dragstart="startDrag($event,id)" @dragend="endDrag"><button class="drag-handle" :aria-label="'调整 '+info(id).name+' 顺序，左右方向键移动'" :title="'拖动调整顺序：'+info(id).name" @keydown.left.prevent="move(id,-1)" @keydown.right.prevent="move(id,1)">⠿</button><span class="native-avatar"><ProviderLogo :provider="id"/></span><strong :title="info(id).name">{{info(id).name}}</strong><small>{{label(id)}}</small><IconButton placement="top" :label="'只展示 '+info(id).name" icon="focus" @click="focus(id)"/><IconButton placement="top" v-if="expandedCount>1" :label="'折叠 '+info(id).name" icon="minus" @click="collapse(id)"/></header><div class="native-surface" :data-native-provider="id"><div v-if="suspended||dragging" class="surface-note">{{suspended?'网页视图暂时收起':'拖动栏位以调整顺序'}}</div><div v-else-if="pageStates[id]?.error" class="page-load-error" role="alert"><span>{{pageStates[id]?.error}}</span><button @click="retry(id)">重试加载</button></div><div v-else class="page-loading" role="status" :aria-label="'正在加载 '+info(id).name"><div class="loading-heading"><span class="loading-spinner"/><span>正在加载 {{info(id).name}}</span></div><div class="skeleton-block short"/><div class="skeleton-block"/><div class="skeleton-block"/><div class="skeleton-block medium"/><div class="skeleton-card"/><p>正在准备原网页，请稍候</p></div></div></article>
   <div v-else class="native-folded" :data-column="id" draggable="true" @dragstart="startDrag($event,id)" @dragend="endDrag" @dragover.prevent @drop.prevent="drop($event,id)"><button :aria-label="'展开 '+info(id).name" :title="info(id).name+' · '+label(id)" @click="expand(id)" @keydown.left.prevent="move(id,-1)" @keydown.right.prevent="move(id,1)"><span class="drag-handle">⠿</span><span class="native-avatar"><ProviderLogo :provider="id"/></span><span class="folded-name">{{info(id).name}}</span><i v-if="['发送中','生成中'].includes(label(id))" class="native-busy"/></button></div>
  </template>
 </div>
</section>
</template>
<style scoped>
.native-conversation{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;padding:0 12px 0 24px;gap:8px}.native-toolbar{display:flex;align-items:center;gap:12px;min-height:38px}.native-toolbar>span{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.native-columns{display:flex;gap:8px;flex:1;min-height:0;min-width:0}.native-column{display:flex;flex-direction:column;flex:1;min-width:0;border:1px solid var(--border);border-radius:8px;overflow:hidden}.native-column>header{cursor:grab;display:flex;align-items:center;gap:8px;height:38px;padding:0 8px;flex-shrink:0;background:var(--surface)}.native-column strong{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}.native-column small{font-size:10px;color:var(--muted);margin-left:auto;white-space:nowrap}.native-avatar{width:22px;height:22px;border-radius:6px;display:block;flex-shrink:0}.native-surface{flex:1;min-height:0;background:var(--surface);display:grid;place-items:center;color:var(--muted);font-size:12px}.native-folded{display:flex;flex-shrink:0;cursor:grab}.native-folded button{width:38px;display:flex;flex-direction:column;align-items:center;gap:12px;padding:10px 4px;border:1px solid var(--border);border-radius:8px;color:var(--muted);background:var(--surface)}.native-folded .folded-name{writing-mode:vertical-rl;font-size:12px;letter-spacing:1px}.native-busy{height:6px;width:6px;border-radius:50%;background:#e9a637}.native-error{font-size:12px;color:#b85f30;display:flex;justify-content:space-between}.native-error button{text-decoration:underline}@media(max-width:1100px){.native-conversation{padding-left:16px}.native-toolbar>span{display:none}}@media(max-width:850px){.native-folded button{width:30px}.native-column small{display:none}}
.drag-handle{font-size:16px;line-height:1;color:var(--muted);padding:0;cursor:grab;flex-shrink:0}.expand-all{font-size:11px;padding:5px 9px;border:1px solid var(--border);border-radius:7px}.is-dragging .native-column,.is-dragging .native-folded{outline:1px dashed var(--muted);outline-offset:-3px}.native-column{container-type:inline-size}@container(max-width:260px){.native-column>header{gap:3px;padding:0 4px}.native-column small{display:none}.native-avatar{width:18px;height:18px}.native-column strong{flex:1}}@container(max-width:160px){.native-column strong{display:none}.native-column .native-avatar{display:none}.native-column .drag-handle{margin-right:auto}.native-column :deep(.icon-button){width:24px;height:24px}}
.page-loading{width:100%;height:100%;padding:28px 18px;overflow:hidden;background:var(--surface)}.loading-heading{display:flex;align-items:center;gap:8px;margin-bottom:30px;white-space:nowrap;font-size:12px}.loading-spinner{width:14px;height:14px;border:2px solid var(--border);border-top-color:var(--muted);border-radius:50%;animation:loading-spin .9s linear infinite;flex-shrink:0}.skeleton-block,.skeleton-card{background:linear-gradient(100deg,var(--hover) 30%,var(--surface) 48%,var(--hover) 68%);background-size:220% 100%;animation:loading-shimmer 1.6s ease-in-out infinite;border-radius:6px}.skeleton-block{height:10px;margin:12px 0}.skeleton-block.short{width:40%;height:18px;margin-bottom:26px}.skeleton-block.medium{width:68%}.skeleton-card{height:90px;margin-top:26px}.page-loading p{font-size:11px;color:var(--muted);margin-top:28px}.page-load-error{padding:20px;display:flex;flex-direction:column;gap:14px;word-break:break-word}.page-load-error button{border:1px solid var(--border);padding:6px 10px;border-radius:8px}.surface-note{padding:20px;text-align:center}@keyframes loading-spin{to{transform:rotate(360deg)}}@keyframes loading-shimmer{to{background-position:-220% 0}}@media(prefers-reduced-motion:reduce){.loading-spinner,.skeleton-block,.skeleton-card{animation:none}}
</style>
